import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { dirname, extname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir } from 'node:fs/promises';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = resolve(process.env.DB_PATH || join(root, 'workboard.sqlite'));
await mkdir(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
  CREATE TABLE IF NOT EXISTS tasks (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL
  );
`);
const projectColumns = db.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some(column => column.name === 'archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');

const mime = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (url.pathname === '/health' && req.method === 'GET') return json(res, 200, { status: 'ok' });
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, db.prepare('SELECT p.id, p.name, p.archived, (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completed_count, (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS total_count FROM projects p ORDER BY p.created_at, p.rowid').all().map(project => ({ ...project, archived: Boolean(project.archived) })));
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/?$/);
  if (tasksMatch && req.method === 'GET') {
    const projectId = decodeURIComponent(tasksMatch[1]);
    if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY created_at, rowid').all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
  }
  if (tasksMatch && req.method === 'POST') {
    try {
      const projectId = decodeURIComponent(tasksMatch[1]);
      const project = db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
      if (!project) return json(res, 404, { error: 'Project not found' });
      if (project.archived) return json(res, 409, { error: 'Archived projects cannot be changed' });
      const body = await readBody(req);
      const title = typeof body.title === 'string' ? body.title.trim() : '';
      if (!title) return json(res, 400, { error: 'Task title is required' });
      const id = randomUUID();
      db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)').run(id, projectId, title, Date.now());
      return json(res, 201, { id, title, completed: false });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/([^/]+)\/?$/);
  if (taskMatch && req.method === 'PATCH') {
    try {
      const body = await readBody(req);
      if (typeof body.completed !== 'boolean') return json(res, 400, { error: 'Invalid completion state' });
      const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id IN (SELECT id FROM projects WHERE archived = 0)').run(Number(body.completed), decodeURIComponent(taskMatch[1]));
      if (!result.changes) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, { completed: body.completed });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/(archive|restore)\/?$/);
  if (archiveMatch && req.method === 'POST') {
    const id = decodeURIComponent(archiveMatch[1]);
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archiveMatch[2] === 'archive' ? 1 : 0, id);
    if (!result.changes) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, { archived: archiveMatch[2] === 'archive' });
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try {
      const body = await readBody(req);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const id = randomUUID();
      db.prepare('INSERT INTO projects (id, name, created_at, archived) VALUES (?, ?, ?, 0)').run(id, name, Date.now());
      return json(res, 201, { id, name });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  if (req.method === 'GET') {
    // Project URLs are client-side routes; serve the app shell on direct visits/reloads.
    const isProjectPage = /^\/projects\/[^/]+\/?$/.test(url.pathname);
    const relative = url.pathname === '/' || isProjectPage ? 'index.html' : url.pathname.replace(/^\/+/, '');
    const path = resolve(root, 'public', relative);
    if (!path.startsWith(resolve(root, 'public') + '/') && path !== resolve(root, 'public')) return text(res, 404, 'Not found');
    try {
      const content = await readFile(path);
      res.writeHead(200, { 'Content-Type': mime[extname(path)] || 'application/octet-stream' });
      return res.end(content);
    } catch { return text(res, 404, 'Not found'); }
  }
  text(res, 404, 'Not found');
});
function json(res, status, value) { res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(value)); }
function text(res, status, value) { res.writeHead(status, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end(value); }
async function readBody(req) {
  let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > 1_000_000) throw new Error('too large'); }
  return JSON.parse(raw || '{}');
}
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}

async function render() {
  const match = location.pathname.match(/^\/projects\/([^/]+)\/?$/);
  if (match) {
    try {
      const projects = await request('/api/projects');
      const project = projects.find(item => item.id === decodeURIComponent(match[1]));
      if (project) {
        renderProject(project);
        return;
      }
    } catch { /* Render the list if project lookup is unavailable. */ }
  }
  app.innerHTML = `<h1>Workboard</h1>
    <label for="project-filter">Project filter</label><select id="project-filter"><option>Active</option><option>Archived</option></select>
    <form id="create-form"><label for="project-name">Project name</label><div class="create-line"><input id="project-name" name="name" type="text"><button type="submit">Create project</button></div></form>
    <p id="alert" class="alert" role="alert" hidden></p><section id="projects" aria-label="Projects"></section>`;
  document.querySelector('#create-form').addEventListener('submit', createProject);
  document.querySelector('#project-filter').addEventListener('change', loadProjects);
  await loadProjects();
}

function renderProject(project) {
  app.innerHTML = `<button class="back" id="back">Projects</button><h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form id="task-form"><label for="task-title">Task title</label><div class="create-line"><input id="task-title" type="text"><button type="submit">Create task</button></div></form>
    <p id="task-alert" class="alert" role="alert" hidden></p>
    <label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
    <section id="tasks" aria-label="Tasks"></section>`;
  document.querySelector('#task-form button').disabled = project.archived;
  document.querySelector('#back').addEventListener('click', () => navigate('/'));
  document.querySelector('#task-form').addEventListener('submit', event => createTask(event, project.id));
  document.querySelector('#task-filter').addEventListener('change', () => loadTasks(project.id, project.archived));
  loadTasks(project.id, project.archived);
}

async function loadTasks(projectId, archived = false) {
  const tasks = await request(`/api/projects/${encodeURIComponent(projectId)}/tasks`);
  const filter = document.querySelector('#task-filter').value;
  const list = document.querySelector('#tasks');
  list.replaceChildren();
  for (const task of tasks) {
    if (filter === 'Open' && task.completed || filter === 'Completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'project-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const label = document.createElement('label');
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox'; checkbox.checked = task.completed;
    checkbox.disabled = archived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      await request(`/api/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      await loadTasks(projectId);
    });
    label.append(checkbox);
    row.append(title, label);
    list.append(row);
  }
}

async function createTask(event, projectId) {
  event.preventDefault();
  const input = document.querySelector('#task-title');
  const alert = document.querySelector('#task-alert');
  const title = input.value.trim();
  if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
  alert.hidden = true;
  try {
    await request(`/api/projects/${encodeURIComponent(projectId)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
    input.value = '';
    await loadTasks(projectId);
  } catch (error) { alert.textContent = error.message; alert.hidden = false; }
}

async function loadProjects() {
  const projects = await request('/api/projects');
  const filter = document.querySelector('#project-filter').value;
  const visibleProjects = projects.filter(project => project.archived === (filter === 'Archived'));
  const list = document.querySelector('#projects');
  list.replaceChildren();
  for (const project of visibleProjects) {
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const button = document.createElement('button');
    button.textContent = 'Open project';
    button.addEventListener('click', () => navigate(`/projects/${encodeURIComponent(project.id)}`));
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completed_count}/${project.total_count} completed`;
    const stateButton = document.createElement('button');
    stateButton.textContent = project.archived ? 'Restore project' : 'Archive project';
    stateButton.addEventListener('click', async () => {
      await request(`/api/projects/${encodeURIComponent(project.id)}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
      await loadProjects();
    });
    row.append(name, summary, button, stateButton);
    list.append(row);
  }
}

async function createProject(event) {
  event.preventDefault();
  const input = document.querySelector('#project-name');
  const alert = document.querySelector('#alert');
  const name = input.value.trim();
  if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; return; }
  alert.hidden = true;
  try {
    await request('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
    input.value = '';
    await loadProjects();
  } catch (error) { alert.textContent = error.message; alert.hidden = false; }
}

function navigate(path) { history.pushState({}, '', path); render(); }
function escapeHtml(value) { return value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]); }
window.addEventListener('popstate', render);
render().catch(error => { app.innerHTML = `<h1>Workboard</h1><p role="alert">${escapeHtml(error.message)}</p>`; });

